mapper.update:
UPDATE pay_payment_intent
SET status=#{status},succeeded_refund_minor=#{succeededRefundMinor},record_version=record_version+1
WHERE tenant_id=#{tenantId} AND payment_id=#{paymentId} AND record_version=#{version}

mapper.select:
SELECT observation_id AS observationId,aggregate_type AS aggregateType,aggregate_id AS aggregateId,
  payload_sha256 AS payloadSha256,merge_result AS mergeResult
FROM pay_provider_observation WHERE tenant_id=#{tenantId} AND observation_id=#{observationId}

mapper.update:
UPDATE pay_tender_allocation SET status='CANCELLED',record_version=record_version+1
WHERE tenant_id=#{tenantId} AND allocation_id=#{allocationId} AND record_version=#{version}
  AND status IN ('PLANNED','FAILED')

UPDATE pay_tender_plan SET status=#{status},succeeded_amount_minor=#{succeededAmount},
  occupied_amount_minor=#{occupiedAmount},record_version=record_version+1
WHERE tenant_id=#{tenantId} AND plan_id=#{planId} AND record_version=#{version}
